/* nepui — Button  */

button:not(:disabled),
[role="button"]:not(:disabled) {
  cursor: pointer;
}

.np-button,
[data-np-button] {
  --np-button-radius: var(--np-radius-md);
  --np-button-font-size: 0.875rem;
  --np-button-font-weight: 500;
  --np-button-gap: 0.375rem;
  --np-button-height: 2rem;
  --np-button-padding-x: 0.625rem;
  --np-button-icon-size: 1rem;

  --np-button-bg: var(--np-primary);
  --np-button-color: var(--np-primary-foreground);
  --np-button-border: transparent;
  --np-button-hover-bg: color-mix(in oklch, var(--np-primary) 80%, transparent);

  --np-button-focus-border: var(--np-ring);
  --np-button-ring: color-mix(in oklch, var(--np-ring), transparent 50%);

  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  position: relative;
  box-sizing: border-box;

  gap: var(--np-button-gap);
  height: var(--np-button-height);
  padding: 0 var(--np-button-padding-x);

  border: 1px solid var(--np-button-border);
  border-radius: var(--np-button-radius);

  background: var(--np-button-bg);
  color: var(--np-button-color);

  font: inherit;
  font-size: var(--np-button-font-size);
  font-weight: var(--np-button-font-weight);
  line-height: 1;

  white-space: nowrap;
  text-decoration: none;
  -webkit-user-select: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;

  transition:
    background-color 150ms ease,
    color 150ms ease,
    border-color 150ms ease,
    box-shadow 150ms ease,
    transform 100ms ease;

  outline: none;
}

:is([data-np-button], .np-button):hover {
  background: var(--np-button-hover-bg);
}

:is([data-np-button], .np-button):active:not([aria-haspopup]) {
  transform: translateY(1px);
}

:is([data-np-button], .np-button):focus-visible {
  border-color: var(--np-button-focus-border);
  box-shadow: 0 0 0 3px var(--np-button-ring);
}

:is([data-np-button], .np-button):disabled,
:is([data-np-button], .np-button)[aria-disabled="true"],
:is([data-np-button], .np-button)[data-disabled] {
  opacity: 0.5;
  pointer-events: none;
}

:is([data-np-button], .np-button)[aria-invalid="true"] {
  border-color: var(--np-destructive);
  box-shadow: 0 0 0 3px
    color-mix(in oklch, var(--np-destructive), transparent 80%);
}

/* Icons: size comes from --np-button-icon-size unless the icon sets its own */
:is([data-np-button], .np-button) svg {
  flex-shrink: 0;
  pointer-events: none;
}

:is([data-np-button], .np-button) svg:not([class*="size-"]) {
  width: var(--np-button-icon-size);
  height: var(--np-button-icon-size);
}

:is([data-np-button], .np-button).np-button-rounded {
  --np-button-radius: 9999px;
}

/* Variants */

.np-button-outline,
:is(.np-button, [data-np-button])[data-variant="outline"] {
  --np-button-bg: var(--np-background);
  --np-button-color: var(--np-foreground);
  --np-button-border: var(--np-border);
  --np-button-hover-bg: color-mix(in oklab, var(--np-muted) 60%, transparent);
}

.np-button-secondary,
:is(.np-button, [data-np-button])[data-variant="secondary"] {
  --np-button-bg: var(--np-secondary);
  --np-button-color: var(--np-secondary-foreground);
  --np-button-hover-bg: color-mix(
    in oklch,
    var(--np-secondary),
    var(--np-foreground) 5%
  );
}

.np-button-ghost,
:is(.np-button, [data-np-button])[data-variant="ghost"] {
  --np-button-bg: transparent;
  --np-button-color: var(--np-foreground);
  --np-button-hover-bg: var(--np-muted);
}

:is(
  .np-button-outline,
  .np-button-ghost,
  :is(.np-button, [data-np-button])[data-variant="outline"],
  :is(.np-button, [data-np-button])[data-variant="ghost"]
)[aria-expanded="true"],
:is(
  .np-button-outline,
  .np-button-ghost,
  :is(.np-button, [data-np-button])[data-variant="outline"],
  :is(.np-button, [data-np-button])[data-variant="ghost"]
)[data-popup-open] {
  background: var(--np-button-hover-bg);
}

.np-button-destructive,
:is(.np-button, [data-np-button])[data-variant="destructive"] {
  --np-button-bg: color-mix(in oklab, var(--np-destructive) 20%, transparent);
  --np-button-color: var(--np-destructive);
  --np-button-hover-bg: color-mix(
    in oklab,
    var(--np-destructive) 30%,
    transparent
  );
  --np-button-focus-border: color-mix(
    in oklch,
    var(--np-destructive),
    transparent 60%
  );
  --np-button-ring: color-mix(in oklab, var(--np-destructive) 40%, transparent);
}

.np-button-link,
:is(.np-button, [data-np-button])[data-variant="link"] {
  --np-button-bg: transparent;
  --np-button-color: var(--np-primary);
  --np-button-hover-bg: transparent;
  text-underline-offset: 4px;
}

:is(
  .np-button-link,
  :is(.np-button, [data-np-button])[data-variant="link"]
):hover {
  text-decoration: underline;
}

/* Sizes */

.np-button-xs,
:is(.np-button, [data-np-button])[data-size="xs"] {
  --np-button-height: 1.5rem;
  --np-button-padding-x: 0.5rem;
  --np-button-font-size: 0.75rem;
  --np-button-gap: 0.25rem;
  --np-button-icon-size: 0.75rem;
  --np-button-radius: min(var(--np-radius-md), 10px);
}

.np-button-sm,
:is(.np-button, [data-np-button])[data-size="sm"] {
  --np-button-height: 1.75rem;
  --np-button-padding-x: 0.625rem;
  --np-button-font-size: 0.8rem;
  --np-button-gap: 0.25rem;
  --np-button-icon-size: 0.875rem;
  --np-button-radius: min(var(--np-radius-md), 12px);
}

.np-button-lg,
:is(.np-button, [data-np-button])[data-size="lg"] {
  --np-button-height: 2.25rem;
  --np-button-padding-x: 0.625rem;
  --np-button-font-size: 0.9375rem;
  --np-button-gap: 0.375rem;
}

.np-button-icon,
:is(.np-button, [data-np-button])[data-size="icon"],
.np-button-icon-xs,
:is(.np-button, [data-np-button])[data-size="icon-xs"],
.np-button-icon-sm,
:is(.np-button, [data-np-button])[data-size="icon-sm"],
.np-button-icon-lg,
.np-button[data-size="icon-lg"] {
  padding: 0;
  aspect-ratio: 1 / 1;
}

.np-button-icon,
:is(.np-button, [data-np-button])[data-size="icon"] {
  --np-button-height: 2rem;
}

.np-button-icon-xs,
:is(.np-button, [data-np-button])[data-size="icon-xs"] {
  --np-button-height: 1.5rem;
  --np-button-icon-size: 0.75rem;
  --np-button-radius: min(var(--np-radius-md), 10px);
}

.np-button-icon-sm,
:is(.np-button, [data-np-button])[data-size="icon-sm"] {
  --np-button-height: 1.75rem;
  --np-button-radius: min(var(--np-radius-md), 12px);
}

.np-button-icon-lg,
:is(.np-button, [data-np-button])[data-size="icon-lg"] {
  --np-button-height: 2.25rem;
}

/* Inside a button group, small sizes use the full radius */
[data-slot="button-group"]
  :is(
    .np-button-xs,
    .np-button-sm,
    .np-button-icon-xs,
    .np-button-icon-sm,
    :is(.np-button, [data-np-button])[data-size="xs"],
    :is(.np-button, [data-np-button])[data-size="sm"],
    :is(.np-button, [data-np-button])[data-size="icon-xs"],
    :is(.np-button, [data-np-button])[data-size="icon-sm"]
  ) {
  --np-button-radius: var(--np-radius-md);
}

@media (prefers-reduced-motion: reduce) {
  :is(.np-button, [data-np-button]):active:not([aria-haspopup]) {
    transform: none;
  }
}
